create or replace function public.create_processing_record(target_organisation_id uuid,input_payload jsonb)
returns uuid language plpgsql security invoker set search_path='privacy','core','audit','extensions','auth','pg_temp' as $$
declare prior privacy.processing_records%rowtype; r privacy.processing_records%rowtype; v int; h text;
begin
 if auth.uid() is null or not core.has_org_role(target_organisation_id,array['super_admin','org_admin']) then raise exception 'privacy_governance_authority_required';end if;
 if nullif(btrim(input_payload->>'purpose_code'),'') is null or nullif(btrim(input_payload->>'purpose_description'),'') is null or nullif(btrim(input_payload->>'legal_basis'),'') is null then raise exception 'processing_record_core_fields_required';end if;
 select * into prior from privacy.processing_records where organisation_id=target_organisation_id and purpose_code=lower(btrim(input_payload->>'purpose_code')) and active order by version desc limit 1 for update;v:=coalesce(prior.version,0)+1;
 h:=encode(extensions.digest(jsonb_build_object('organisation_id',target_organisation_id,'purpose_code',lower(btrim(input_payload->>'purpose_code')),'purpose_description',btrim(input_payload->>'purpose_description'),'legal_basis',btrim(input_payload->>'legal_basis'),'data_categories',coalesce(input_payload->'data_categories','[]'::jsonb),'subject_categories',coalesce(input_payload->'subject_categories','[]'::jsonb),'recipients',coalesce(input_payload->'recipients','[]'::jsonb),'retention_days',nullif(input_payload->>'retention_days','')::int,'version',v)::text,'sha256'),'hex');
 perform set_config('conceptspaces.privacy_phase','processing',true);
 if prior.id is not null then update privacy.processing_records set active=false where id=prior.id;end if;
 insert into privacy.processing_records(organisation_id,purpose_code,purpose_description,legal_basis,data_categories,subject_categories,recipients,retention_days,version,supersedes_id,created_by,record_hash)
 values(target_organisation_id,lower(btrim(input_payload->>'purpose_code')),btrim(input_payload->>'purpose_description'),btrim(input_payload->>'legal_basis'),coalesce(input_payload->'data_categories','[]'::jsonb),coalesce(input_payload->'subject_categories','[]'::jsonb),coalesce(input_payload->'recipients','[]'::jsonb),nullif(input_payload->>'retention_days','')::int,v,prior.id,auth.uid(),h) returning * into r;
 perform audit.append_event(target_organisation_id,null,'privacy.processing_record_created','processing_record',r.id,null,to_jsonb(r),h,gen_random_uuid());return r.id;
end;$$;
