create or replace function public.record_privacy_consent(target_organisation_id uuid,input_payload jsonb)
returns uuid language plpgsql security invoker set search_path='privacy','core','audit','extensions','auth','pg_temp' as $$
declare r privacy.consent_records%rowtype; status_value text:=lower(btrim(input_payload->>'status')); h text;
