 h:=encode(extensions.digest(jsonb_build_object('organisation_id',target_organisation_id,'subject_reference',btrim(input_payload->>'subject_reference'),'purpose_code',lower(btrim(input_payload->>'purpose_code')),'legal_basis',btrim(input_payload->>'legal_basis'),'status',status_value,'evidence_ref',btrim(input_payload->>'evidence_ref'))::text,'sha256'),'hex');
 perform set_config('conceptspaces.privacy_phase','consent',true);
 insert into privacy.consent_records(organisation_id,subject_user_id,subject_reference,purpose_code,legal_basis,status,evidence_ref,evidence_hash,effective_at,withdrawn_at,created_by)
 values(target_organisation_id,nullif(input_payload->>'subject_user_id','')::uuid,btrim(input_payload->>'subject_reference'),lower(btrim(input_payload->>'purpose_code')),btrim(input_payload->>'legal_basis'),status_value,btrim(input_payload->>'evidence_ref'),h,coalesce(nullif(input_payload->>'effective_at','')::timestamptz,now()),case when status_value='withdrawn' then now() end,auth.uid()) returning * into r;
 perform audit.append_event(target_organisation_id,null,'privacy.consent_'||status_value,'consent_record',r.id,null,to_jsonb(r),h,gen_random_uuid());return r.id;
end;$$;
