create or replace function public.approve_retention_policy(target_policy_id uuid,target_reason text)
returns text language plpgsql security invoker set search_path='privacy','core','audit','auth','pg_temp' as $$
declare r privacy.retention_policies%rowtype; before_state jsonb;
begin
 select * into r from privacy.retention_policies where id=target_policy_id for update;if not found then raise exception 'retention_policy_not_found';end if;
