 update privacy.retention_policies set status='active',approved_by=auth.uid(),approved_at=now() where id=r.id returning * into r;
 perform audit.append_event(r.organisation_id,null,'privacy.retention_policy_approved','retention_policy',r.id,before_state,to_jsonb(r),target_reason,gen_random_uuid());return r.status;
end;$$;
revoke all on function public.approve_retention_policy(uuid,text) from public,anon;grant execute on function public.approve_retention_policy(uuid,text) to authenticated;

