create or replace function public.authorize_document_download(target_document_id uuid,target_export_request_id uuid default null)
returns jsonb language plpgsql security invoker set search_path='privacy','cde','project','engagement','audit','auth','pg_temp' as $$
declare d cde.documents%rowtype;p project.projects%rowtype;internal_mode boolean;client_ok boolean:=false;allowed boolean:=false;watermark boolean:=false;export_ok boolean:=false;reason_value text;
begin select * into d from cde.documents where id=target_document_id;if not found then raise exception 'document_not_found';end if;select * into p from project.projects where id=d.project_id;if auth.uid() is null then raise exception 'authentication_required';end if;internal_mode:=project.can_access_project(p.id);client_ok:=engagement.client_can_access_project(p.id) and exists(select 1 from engagement.client_portal_access a where a.project_id=p.id and a.user_id=auth.uid() and a.status='active' and coalesce((a.permissions->>'download_documents')::boolean,false));
 if d.status not in ('approved','issued') then reason_value:='document_not_approved_or_issued';elsif client_ok and d.cde_state<>'published' then reason_value:='client_download_requires_published_document';elsif p.data_classification='public' then allowed:=internal_mode or client_ok;elsif p.data_classification='internal' then allowed:=internal_mode;if not allowed then reason_value:='internal_classification_block';end if;elsif p.data_classification='confidential' then allowed:=project.can_manage_project(p.id);watermark:=allowed;if not allowed then reason_value:='confidential_download_management_authority_required';end if;elsif p.data_classification='restricted' then if target_export_request_id is not null then export_ok:=exists(select 1 from privacy.project_export_requests r where r.id=target_export_request_id and r.document_id=d.id and r.project_id=p.id and r.requested_by=auth.uid() and r.status='approved' and r.expires_at>now());end if;allowed:=export_ok;watermark:=allowed;if not allowed then reason_value:='CLASSIFICATION_BLOCK';end if;end if;
 if allowed then perform audit.append_event(p.organisation_id,p.id,'security.download_authorized','document',d.id,null,jsonb_build_object('classification',p.data_classification,'revision',d.revision,'export_request_id',target_export_request_id,'watermark_required',watermark),null,gen_random_uuid());else perform audit.append_event(p.organisation_id,p.id,'security.download_blocked','document',d.id,null,jsonb_build_object('classification',p.data_classification,'reason',coalesce(reason_value,'permission_denied')),coalesce(reason_value,'permission_denied'),gen_random_uuid());end if;return jsonb_build_object('allowed',allowed,'classification',p.data_classification,'watermark_required',watermark,'reason',case when allowed then null else coalesce(reason_value,'permission_denied') end,'document_id',d.id,'revision',d.revision);end;$$;
revoke all on function public.authorize_document_download(uuid,uuid) from public,anon;grant execute on function public.authorize_document_download(uuid,uuid) to authenticated;

create or replace function public.verify_audit_chain(target_organisation_id uuid)
returns jsonb language plpgsql stable security invoker set search_path='audit','core','extensions','auth','pg_temp' as $$
declare e audit.events%rowtype;expected_previous text:=null;computed text;first_bad uuid:=null;checked_count bigint:=0;
begin if auth.uid() is null or not core.is_internal_org_member(target_organisation_id) then raise exception 'organisation_access_required';end if;for e in select * from audit.events where organisation_id=target_organisation_id order by created_at,id loop checked_count:=checked_count+1;if e.previous_hash is distinct from expected_previous then first_bad:=e.id;exit;end if;computed:=encode(extensions.digest(concat_ws('|',coalesce(e.previous_hash,''),e.id::text,e.organisation_id::text,coalesce(e.project_id::text,''),coalesce(e.actor_id::text,''),e.action,e.resource_type,coalesce(e.resource_id::text,''),coalesce(e.before_state::text,''),coalesce(e.after_state::text,''),coalesce(e.reason,''),e.correlation_id::text,e.created_at::text),'sha256'),'hex');if computed<>e.event_hash then first_bad:=e.id;exit;end if;expected_previous:=e.event_hash;end loop;return jsonb_build_object('valid',first_bad is null,'checked_events',checked_count,'first_invalid_event_id',first_bad,'chain_head',expected_previous);end;$$;
