create or replace function public.list_privacy_security_workspace(target_organisation_id uuid)
returns jsonb language plpgsql stable security invoker set search_path='privacy','project','core','auth','pg_temp' as $$
begin if auth.uid() is null or not core.is_internal_org_member(target_organisation_id) then raise exception 'organisation_access_required';end if;return jsonb_build_object('processing',coalesce((select jsonb_agg(to_jsonb(r) order by r.purpose_code,r.version desc) from privacy.processing_records r where r.organisation_id=target_organisation_id),'[]'::jsonb),'consents',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at desc) from privacy.consent_records r where r.organisation_id=target_organisation_id),'[]'::jsonb),'retention',coalesce((select jsonb_agg(to_jsonb(r) order by r.record_class,r.version desc) from privacy.retention_policies r where r.organisation_id=target_organisation_id),'[]'::jsonb),'requests',coalesce((select jsonb_agg(to_jsonb(r) order by r.requested_at desc) from privacy.data_subject_requests r where r.organisation_id=target_organisation_id),'[]'::jsonb),'exports',coalesce((select jsonb_agg(to_jsonb(r) order by r.requested_at desc) from privacy.project_export_requests r where r.organisation_id=target_organisation_id and project.can_access_project(r.project_id)),'[]'::jsonb),'projects',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'code',p.code::text,'name',p.name,'classification',p.data_classification) order by p.name) from project.projects p where p.organisation_id=target_organisation_id and project.can_access_project(p.id)),'[]'::jsonb));end;$$;
